{"slice":{"slice_id":"s_arbre","introduces":[{"id":"noeud0","type":"point","params":{"at":[0,3]}},{"id":"branche_r1","type":"line","params":{"from":[0,3],"to":[-4,6]}},{"id":"branche_b1","type":"line","params":{"from":[0,3],"to":[-4,0]}},{"id":"lab_r1","type":"label","content":"R : 5/8","attachment":{"parent":"branche_r1","anchor":"center"}},{"id":"lab_b1","type":"label","content":"B : 3/8","attachment":{"parent":"branche_b1","anchor":"center"}},{"id":"noeud_r","type":"point","params":{"at":[-4,6]}},{"id":"noeud_b","type":"point","params":{"at":[-4,0]}},{"id":"p_rb","type":"line","params":{"from":[-4,6],"to":[-8,8]}},{"id":"p_br","type":"line","params":{"from":[-4,6],"to":[-8,4]}},{"id":"p_bb","type":"line","params":{"from":[-4,0],"to":[-8,2]}},{"id":"p_bb2","type":"line","params":{"from":[-4,0],"to":[-8,-2]}},{"id":"lab_rb","type":"label","content":"B : 3/7","attachment":{"parent":"p_rb","anchor":"center"}},{"id":"lab_br","type":"label","content":"R : 4/7","attachment":{"parent":"p_br","anchor":"center"}},{"id":"lab_bb","type":"label","content":"B : 2/7","attachment":{"parent":"p_bb","anchor":"center"}},{"id":"lab_bb2","type":"label","content":"R : 5/7","attachment":{"parent":"p_bb2","anchor":"center"}}],"beats":[{"id":"premier","say":"Premier tirage : il y a 5 rouges sur 8 boules, donc la probabilité de tirer une rouge est cinq huitièmes, et celle de tirer une bleue est trois huitièmes.","cues":[{"id":"c_5_8","text":"cinq huitièmes"},{"id":"c_3_8","text":"trois huitièmes"}],"do":[{"id":"s_n0","verb":"show","target":"noeud0","at":"beat:start"},{"id":"w_br1","verb":"write","target":"branche_r1","at":"cue:c_5_8"},{"id":"w_lr1","verb":"write","target":"lab_r1","at":"cue:c_5_8"},{"id":"w_bb1","verb":"write","target":"branche_b1","at":"cue:c_3_8"},{"id":"w_lb1","verb":"write","target":"lab_b1","at":"cue:c_3_8"}],"pause_after":"normal"},{"id":"second","say":"Mais on tire sans remise : la boule tirée ne revient pas dans le sac. Il ne reste que 7 boules pour le deuxième ti