{"slice":{"slice_id":"s_chemins","introduces":[{"id":"eq_chemin","type":"math","content":"P(RB) = \\frac{5}{8} \\times \\frac{3}{7} = \\frac{15}{56}"},{"id":"eq_chemin2","type":"math","content":"P(BR) = \\frac{3}{8} \\times \\frac{4}{7} = \\frac{12}{56}","layout":{"next_to":"eq_chemin","direction":"down","gap":"md"}}],"beats":[{"id":"suite_r","say":"Si la première est rouge, il reste 4 rouges et 3 bleues sur 7 boules : la probabilité d'une bleue ensuite est trois septièmes.","cues":[{"id":"c_trois_sept","text":"trois septièmes"}],"do":[{"id":"d_p_rb","verb":"draw","target":"p_rb","at":"beat:start"},{"id":"s_n_r","verb":"show","target":"noeud_r","at":"beat:start"},{"id":"d_p_br","verb":"draw","target":"p_br","at":"beat:start"},{"id":"w_lrb","verb":"write","target":"lab_rb","at":"cue:c_trois_sept"},{"id":"w_lbr","verb":"write","target":"lab_br","at":"cue:c_trois_sept"}],"pause_after":"normal"},{"id":"var","say":"Si la première est bleue, il reste 5 rouges et 2 bleues : la probabilité d'une bleue ensuite est deux septièmes.","cues":[{"id":"c_deux_sept","text":"deux septièmes"}],"do":[{"id":"d_p_bb","verb":"draw","target":"p_bb","at":"beat:start"},{"id":"s_n_b","verb":"show","target":"noeud_b","at":"beat:start"},{"id":"d_p_bb2","verb":"draw","target":"p_bb2","at":"beat:start"},{"id":"w_lbb","verb":"write","target":"lab_bb","at":"cue:c_deux_sept"},{"id":"w_lbb2","verb":"write","target":"lab_bb2","at":"cue:c_deux_sept"}],"pause_after":"long"}]}}
